      const total = UmrahCore_N(o.total);
      if (total <= 0)
        throw new Error("قيمة الالتزام غير صحيحة");
      if (!(UmrahCore_Bridge2.rate(o.currency || p.currency, o.date || p.departureDate || UmrahCore_today()) > 0))
        throw new Error(`سعر صرف ${o.currency || p.currency} غير موجود`);
      const key = o.key || `commit:${o.sourceType || "manual"}:${o.sourceId || UmrahCore_iid()}:${p.id}`;
