      const res = UmrahCore_Bridge2.emit("umrah.supplier.commitment.requested", payload, key);
      c = { id: UmrahCore_iid(), branchId: p.branchId || UmrahCore_Bridge2.branchId(), key, programId: p.id, supplierId: o.supplierId, currency: payload.currency, total, qty: payload.qty, unitPrice: payload.unitPrice, description: payload.description, sourceType: payload.sourceType, sourceId: payload.sourceId, sourceCostId: o.sourceCostId || "", status: "committed", hostPOId: res?.purchaseOrderId || "", hostPONo: res?.purchaseOrderNo || "", hostInvoiceId: "", hostInvoiceNo: "", createdAt: UmrahCore_now() };
      UmrahCore_DB2.data.supplierCommitments.unshift(c);
