      if (booking && x.category === "flight")
        qty = Math.max(0, UmrahCore_N(booking.persons) - UmrahCore_N(booking.infants));
      const calc = x.mode === "perPax" ? UmrahCore_N(x.amount) * qty : UmrahCore_N(x.amount), total = UmrahCore_N(overrideAmount) || calc, key = booking ? `booking-cost:${booking.id}:${x.id}` : `program-cost:${p.id}:${x.id}`;
