      const permitRequired = p.programType === "hajj", campRequired = p.programType === "hajj", body = `<div class="automation-note mb-12"><b>${UmrahCore_esc(t.nameAr || t.no)}</b> • ${UmrahCore_esc(UmrahCore_programDisplay(p))}<br>تتبع داخلي لخدمات الحج مرتبط بملف المسافر والجاهزية؛ لا يدّعي اتصالًا خارجيًا بمنصة نسك.</div><div class="form-grid two"><div class="field"><label>حالة التصريح / نسك ${permitRequired ? "*" : ""}</label><select name="hajjPermitStatus"><option value="not_started" ${t.hajjPermitStatus === "not_started" ? "selected" : ""}>لم يبدأ</option><option value="documents_received" ${t.hajjPermitStatus === "documents_received" ? "selected" : ""}>استلام المستندات</option><option value="submitted" ${t.hajjPermitStatus === "submitted" ? "selected" : ""}>تم التقديم</option><option value="processing" ${t.hajjPermitStatus === "processing" ? "selected" : ""}>تحت الإجراء</option><option value="issued" ${t.hajjPermitStatus === "issued" ? "selected" : ""}>صادر</option><option value="rejected" ${t.hajjPermitStatus === "rejected" ? "selected" : ""}>مرفوض</option></select></div><div class="field"><label>رقم التصريح / نسك</label><input name="hajjPermitNo" value="${UmrahCore_esc(t.hajjPermitNo || "")}" placeholder="يصبح إلزاميًا عند الإصدار"></div><div class="field full"><label>تسكين المخيم / المشاعر ${campRequired ? "*" : ""}</label><input name="campAssignment" value="${UmrahCore_esc(t.campAssignment || "")}" placeholder="مثال: مخيم A — بوابة 3 — سرير 12"></div></div><div class="entity-link-bar"><button type="button" class="btn small ghost" data-open-attachment-type="traveler" data-open-attachment-id="${UmrahCore_esc(t.id)}">مرفقات المسافر</button><button type="button" class="btn small ghost" data-umrah-open-documents-close="1">المستندات والتقارير</button></div>`;
